    reconcileOnboardingPendingConnector: {
        parameters: {
            query?: never;
            header?: never;
            path: {
                /** @description The onboarding id. */
                id: string;
            };
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description What the reconcile did, and the onboarding as it now stands. */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["ReconcilePendingConnectorResponseDto"];
                };
            };
            /** @description `INVALID_STEP_DATA`: The submitted data violates the current step; `errors` maps each refused field to its reasons (`UNKNOWN`, `REQUIRED`, `INVALID`, `CALLBACK_ONLY`, or a connector's own), and the onboarding stays where it was. */
            400: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["ApiError"] & {
                        /** @enum {string} */
                        code?: "INVALID_STEP_DATA";
                    };
                };
            };
            /** @description No bearer token, or the token fails signature, issuer, audience or expiry verification. */
            401: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["NestHttpError"];
                };
            };
            /** @description The token verifies but its `roles` claim holds none of `ADMIN_REQUIRED_ROLES`; signing in again cannot fix this. */
            403: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["NestHttpError"];
                };
            };
            /**
             * @description `ONBOARDING_NOT_FOUND`: No onboarding has this id.
             *
             *     `WORKFLOW_NOT_FOUND`: No published workflow has this id, or no revision of it carries the pinned version.
             */
            404: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["ApiError"] & {
                        /** @enum {string} */
                        code?: "ONBOARDING_NOT_FOUND" | "WORKFLOW_NOT_FOUND";
                    };
                };
            };
            /**
             * @description `ONBOARDING_NOT_AWAITING_CONNECTOR`: The onboarding is not parked on a connector, so there is no provider attempt to read back.
             *
             *     `PENDING_CONNECTOR_RECONCILE_UNSUPPORTED`: The parked connector cannot be reconciled: its adapter offers no read-back from the provider (`reason: adapter`), or the park records no provider attempt to read (`reason: reference_missing`). Wait for the callback, or review the onboarding by hand.
             *
             *     `ONBOARDING_COMPLETED`: The onboarding is already approved or completed and accepts no further moves.
             *
             *     `UNKNOWN_WORKFLOW_EVALUATION`: The workflow produced no outcome the engine can apply; the onboarding is left unchanged.
             */
            409: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["ApiError"] & {
                        /** @enum {string} */
                        code?: "ONBOARDING_NOT_AWAITING_CONNECTOR" | "PENDING_CONNECTOR_RECONCILE_UNSUPPORTED" | "ONBOARDING_COMPLETED" | "UNKNOWN_WORKFLOW_EVALUATION";
                    };
                };
            };
            /** @description `WORKFLOW_RETIRED`: The pinned revision is retired and can no longer be read or run. */
            410: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["ApiError"] & {
                        /** @enum {string} */
                        code?: "WORKFLOW_RETIRED";
                    };
                };
            };
            /**
             * @description A connector failed in a way its adapter raises as a plain error rather than one of the codes below: an `http_request` call that could not be sent or answered with an unexpected status, a Sumsub level or credential that does not resolve, or a Veriff credential or payload that does not resolve. The framework answers with its own envelope, so there is no `code` to branch on; the connector, the step and the reason are in the audit trail.
             *
             *     `CLIENT_WEBHOOK_DELIVERY_FAILED`: The client webhook for this move could not be delivered; the outbox entry was returned to pending for the worker to retry.
             *
             *     `OTP_DELIVERY_FAILED`: The one-time code could not be delivered: the SMS provider or the mail transport could not be reached, or answered with an error.
             *
             *     `SENDGRID_EMAIL_UNAVAILABLE`: SendGrid could not be reached, or answered with an error the adapter does not map to an outcome.
             *
             *     `SUMSUB_UNAVAILABLE`: Sumsub could not be reached, or answered with an error the adapter does not map to an outcome.
             *
             *     `VERIFF_UNAVAILABLE`: Veriff could not be reached, or answered with an error the adapter does not map to an outcome.
             */
            500: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["NestHttpError"] | (components["schemas"]["ApiError"] & {
                        /** @enum {string} */
                        code?: "CLIENT_WEBHOOK_DELIVERY_FAILED" | "OTP_DELIVERY_FAILED" | "SENDGRID_EMAIL_UNAVAILABLE" | "SUMSUB_UNAVAILABLE" | "VERIFF_UNAVAILABLE";
                    });
                };
            };
            /**
             * @description `AGREEMENT_NOT_PUBLISHED`: The workflow declares an agreement family nobody has published a version of; `key` names it. An operator publishes one and the same request then succeeds.
             *
             *     `CONNECTOR_NOT_CONFIGURED`: A connector the step calls has a required setting with no value; carries `connectorId` and `key`.
             *
             *     Entra's signing key set could not be reached, so the token was never judged. Retry.
             */
            503: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["NestHttpError"];
                };
            };
        };
    };
